#!/usr/bin/env bash
# new_role_keys.sh: mint the fresh r1006 role keys (owner decision 2026-10-26). OWNER-RUN.
#
# r1006 shares chain id 40204 with earlier chains on which the 09-29 reroll keys
# transacted, so a funded r1006 account on such a key could have its earlier
# transactions replayed. Every role below gets a NEW key:
#   TREASURY FAUCET RELAYER TEAM SIGNER_1 SIGNER_2 SIGNER_3 CITRATE_AA_OWNER
#   CITRATE_AA_IDENTITY_SIGNER CITRATE_AA_SPONSOR_SIGNER MEMBERSHIP_GRANTOR GOV4 GOV5
#
# Each key is generated by `cast wallet new --json` and piped straight into a helper that
# writes it to DIR/<ROLE>.key (mode 0600, DIR mode 0700, umask 077, O_EXCL: an existing key
# is never overwritten). The key never reaches argv, a log or the terminal. Only the
# address is printed, and written to DIR/<ROLE>.addr and DIR/addresses.env.
#
#   new_role_keys.sh [--dir DIR]                 (default ~/.citrate-r1006-keys)
#   new_role_keys.sh --check-live URL [--dir DIR]
#       read-only: every address in DIR/addresses.env has nonce 0 and balance 0 at URL
# Then: make_inputs.py --addresses DIR/addresses.env > scripts/genesis/r1006/inputs.r1006.env
set -euo pipefail
ROLES=(TREASURY FAUCET RELAYER TEAM SIGNER_1 SIGNER_2 SIGNER_3 CITRATE_AA_OWNER CITRATE_AA_IDENTITY_SIGNER
  CITRATE_AA_SPONSOR_SIGNER MEMBERSHIP_GRANTOR GOV4 GOV5)
DIR="$HOME/.citrate-r1006-keys" LIVE=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --dir) DIR="$2"; shift 2 ;;
    --check-live) LIVE="$2"; shift 2 ;;
    *) echo "new_role_keys: unknown argument $1" >&2; exit 2 ;;
  esac
done
if [[ -n "$LIVE" ]]; then
  rc=0
  while IFS='=' read -r role addr; do
    [[ "$role" =~ ^[A-Z0-9_]+$ && "$addr" =~ ^0x[0-9a-fA-F]{40}$ ]] || continue
    n=$(cast nonce "$addr" --rpc-url "$LIVE") b=$(cast balance "$addr" --rpc-url "$LIVE")
    if [[ "$n" == 0 && "$b" == 0 ]]; then echo "ok    $role $addr (nonce 0, balance 0)"; else echo "FAIL  $role $addr nonce $n balance $b"; rc=1; fi
  done <"$DIR/addresses.env"
  exit $rc
fi
umask 077
mkdir -p "$DIR"
chmod 700 "$DIR"
for role in "${ROLES[@]}"; do
  if [[ -e "$DIR/$role.key" ]]; then
    echo "keep  $role $(cat "$DIR/$role.addr") (key exists; not regenerated)"
    continue
  fi
  cast wallet new --json | python3 -c '
import json, os, sys
d, role = sys.argv[1], sys.argv[2]
w = json.load(sys.stdin)
if isinstance(w, dict) and "data" in w:  # cast >= 1.8 wraps output in an envelope
    w = w["data"]
w = w[0] if isinstance(w, list) else w
addr, key = w["address"], w["private_key"]
fd = os.open(os.path.join(d, role + ".key"), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
with os.fdopen(fd, "w") as f:
    f.write(key + "\n")
del key, w
with open(os.path.join(d, role + ".addr"), "w") as f:
    f.write(addr + "\n")
with open(os.path.join(d, "addresses.env"), "a") as f:
    f.write(f"{role}={addr}\n")
print(f"new   {role} {addr}")
' "$DIR" "$role"
done
echo "addresses: $DIR/addresses.env (keys stay in $DIR, mode 0600)"
